/* Keep the mobile title and glass on one clipped moving shutter. */
(()=>{function apply(){const host=document.querySelector('#ah2123-mobile-critical');if(!host)return;let glass=host.querySelector('.ah-mobile-critical-glass');if(!glass){glass=document.createElement('div');glass.className='ah-mobile-critical-glass';glass.style.cssText='position:absolute;inset:0;z-index:100;pointer-events:none;background:rgba(2,8,14,.7);transition:transform .75s ease;';host.append(glass);}host.style.setProperty('overflow','hidden','important');for(const n of host.querySelectorAll(':scope>.ah2123-critical-window-label,:scope>.ah-single-window-surface,:scope>.ah-clean-surface-matte'))glass.append(n);const surface=glass.querySelector('.ah-single-window-surface');if(surface){surface.style.setProperty('display','none','important');surface.style.setProperty('opacity','0','important');surface.style.setProperty('transform','none','important');}for(const matte of glass.querySelectorAll('.ah-clean-surface-matte'))matte.style.setProperty('display','none','important');const label=glass.querySelector('.ah2123-critical-window-label');if(label){label.style.setProperty('display','flex','important');label.style.setProperty('transform','none','important');label.style.setProperty('opacity','1','important');label.style.setProperty('z-index','101','important');for(const[k,v]of Object.entries({position:'absolute',inset:'0',width:'100%',height:'100%',margin:'0',padding:'16px','box-sizing':'border-box',display:'flex','flex-direction':'column','align-items':'center','justify-content':'center','text-align':'center',background:'transparent','box-shadow':'none'}))label.style.setProperty(k,v,'important');}glass.style.transform=host.classList.contains('ah2123-critical-open')?'translateY(-105%)':'translateY(0)';}let queued=false;function queue(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;apply()})}new MutationObserver(queue).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});addEventListener('load',queue);queue()})();

